<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import FullCalendar from '@fullcalendar/vue3'
import timeGridPlugin from '@fullcalendar/timegrid'
import dayGridPlugin from '@fullcalendar/daygrid'
import interactionPlugin from '@fullcalendar/interaction'
import zhLocale from '@fullcalendar/core/locales/zh-cn'
import { ArrowUpRight, ArrowRight, CalendarDays, Check, ChevronLeft, ChevronRight, Circle, Clock3, Inbox, Layers, LayoutDashboard, LockKeyhole, MessageSquare, MoreHorizontal, Plus, Search, Settings2, Sparkles, Sun, Undo2, X, ChartNoAxesColumnIncreasing, Trash2, CheckCheck, AlertCircle, PanelRightClose, Menu, Leaf, Send, LoaderCircle } from 'lucide-vue-next'
import { usePlanner } from './stores/planner'
import { api, wallTime, toISO, hours } from './services/api'
import type { Task, Block, CalendarEvent, Settings, Parsed, Project } from './types'
const store=usePlanner(), page=ref('today'), calendar=ref<InstanceType<typeof FullCalendar>>(), calendarView=ref('timeGridWeek'), calTitle=ref(''), mobileNav=ref(false)
const nav=[{id:'today',label:'今日概览',icon:LayoutDashboard},{id:'calendar',label:'我的日历',icon:CalendarDays},{id:'inbox',label:'任务箱',icon:Inbox},{id:'projects',label:'项目',icon:Layers},{id:'stats',label:'专注统计',icon:ChartNoAxesColumnIncreasing}]
const data=computed(()=>store.data!), tz=computed(()=>data.value?.settings.timezone||'Asia/Shanghai'), clock=ref(new Date())
let ticker:ReturnType<typeof setInterval>
onMounted(()=>{store.run(store.load);ticker=setInterval(()=>clock.value=new Date(),60000)})
onUnmounted(()=>clearInterval(ticker))
const today=computed(()=>wallTime(clock.value.toISOString(),tz.value).slice(0,10))
const dateLabel=computed(()=>new Intl.DateTimeFormat('zh-CN',{timeZone:tz.value,month:'long',day:'numeric',weekday:'long'}).format(clock.value))
const pending=computed(()=>data.value?.tasks.filter(t=>t.status!=='done')||[])
const completed=computed(()=>data.value?.tasks.filter(t=>t.status==='done')||[])
const activeBlocks=computed(()=>data.value?.schedule.blocks.filter(b=>pending.value.some(t=>t.id===b.task_id)&&new Date(b.end_at)>clock.value)||[])
const todayBlocks=computed(()=>activeBlocks.value.filter(b=>wallTime(b.start_at,tz.value).startsWith(today.value)))
const riskList=computed(()=>data.value?.schedule.risks.filter(r=>r.level!=='ok')||[])
const urgent=computed(()=>pending.value.filter(t=>t.deadline && new Date(t.deadline).getTime()-clock.value.getTime()<172800000))
const progress=computed(()=>data.value?.tasks.length?Math.round(completed.value.length/data.value.tasks.length*100):0)
const taskById=(id:string)=>data.value?.tasks.find(t=>t.id===id)
const projectById=(id:string|null)=>data.value?.projects.find(p=>p.id===id)
const color=(t?:Task)=>projectById(t?.project_id||null)?.color||'#657d68'
const timeLabel=(iso:string)=>wallTime(iso,tz.value).slice(11,16)
function deadlineLabel(t:Task){if(t.deadline)return new Intl.DateTimeFormat('zh-CN',{timeZone:tz.value,month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(t.deadline));if(t.deadline_date)return t.deadline_date+' · 时间待确认';return '无截止日期'}
const calendarOptions=computed<any>(()=>({plugins:[timeGridPlugin,dayGridPlugin,interactionPlugin],initialView:calendarView.value,initialDate:today.value,timeZone:'UTC',locale:zhLocale,firstDay:1,headerToolbar:false,height:'auto',allDaySlot:false,slotMinTime:'07:00',slotMaxTime:'23:00',slotDuration:'00:30',snapDuration:'00:15',slotLabelInterval:'01:00',expandRows:true,now:wallTime(clock.value.toISOString(),tz.value),nowIndicator:true,editable:true,selectable:true,dayHeaderFormat:{weekday:'short',day:'numeric'},eventTimeFormat:{hour:'2-digit',minute:'2-digit',hour12:false},slotLabelFormat:{hour:'2-digit',minute:'2-digit',hour12:false},events:[
 ...data.value.events.map(e=>({id:'e:'+e.id,title:e.title,start:wallTime(e.start_at,tz.value),end:wallTime(e.end_at,tz.value),backgroundColor:e.color+'18',borderColor:e.color,textColor:e.color,editable:false,extendedProps:{fixed:true,event:e}})),
 ...activeBlocks.value.map(b=>({id:b.id,title:(b.is_locked?'⌑ ':'')+(taskById(b.task_id)?.title||''),start:wallTime(b.start_at,tz.value),end:wallTime(b.end_at,tz.value),backgroundColor:color(taskById(b.task_id))+'18',borderColor:color(taskById(b.task_id)),textColor:color(taskById(b.task_id)),editable:!b.is_locked&&new Date(b.start_at)>clock.value,extendedProps:{block:b}}))],eventDidMount:(info:any)=>{info.el.style.color=info.event.textColor},datesSet:(info:any)=>calTitle.value=info.view.title,eventClick:(info:any)=>{if(info.event.extendedProps.fixed){selectedEvent.value=info.event.extendedProps.event;dialog.value='eventDetail'}else{selectedBlock.value=info.event.extendedProps.block;dialog.value='block'}},eventDrop:moveCalendarBlock,eventResize:moveCalendarBlock,select:(info:any)=>{openEvent();eventForm.value.start_at=info.startStr.slice(0,16);eventForm.value.end_at=info.endStr.slice(0,16)}}))
async function moveCalendarBlock(info:any){await store.run(async()=>{try{await api('/schedule/blocks/'+info.event.id,'PATCH',{start_at:toISO(info.event.start.toISOString().slice(0,19),tz.value),end_at:toISO(info.event.end.toISOString().slice(0,19),tz.value),is_locked:true});await store.load();store.notify('已移动并锁定此安排')}catch(e){info.revert();throw e}})}
function navigate(direction:number){const c=calendar.value?.getApi();if(direction===0)c?.gotoDate(today.value);else direction>0?c?.next():c?.prev()}
function changeView(view:string){calendarView.value=view;calendar.value?.getApi().changeView(view)}
function go(id:string){page.value=id;mobileNav.value=false}
const dialog=ref(''), selectedBlock=ref<Block|null>(null),selectedEvent=ref<CalendarEvent|null>(null)
const draft=ref<Task>(blankTask()),deadlineInput=ref(''),earliestInput=ref(''),deadlineMode=ref('exact')
function blankTask():Task{return {id:'',title:'',project_id:null,deadline:null,deadline_date:null,deadline_type:'none',priority:2,estimated_minutes:60,remaining_minutes:60,status:'todo',earliest_start:null,splittable:true,min_block_minutes:30,max_block_minutes:120,preferred_period:'any',dependencies:[],notes:''}}
function openTask(task?:Task){draft.value=task?JSON.parse(JSON.stringify(task)):blankTask();deadlineMode.value=task?.deadline_date?'date':'exact';deadlineInput.value=task?.deadline?wallTime(task.deadline,tz.value).slice(0,16):task?.deadline_date||'';earliestInput.value=task?.earliest_start?wallTime(task.earliest_start,tz.value).slice(0,16):'';dialog.value='task'}
function normalizeTask(t:Task){const result={...t};if(result.status==='done')result.remaining_minutes=0;return result}
async function saveTask(){await store.run(async()=>{const t=normalizeTask({...draft.value,deadline:deadlineInput.value&&deadlineMode.value==='exact'?toISO(deadlineInput.value,tz.value):null,deadline_date:deadlineInput.value&&deadlineMode.value==='date'?deadlineInput.value.slice(0,10):null,deadline_type:deadlineInput.value?draft.value.deadline_type==='none'?'hard':draft.value.deadline_type:'none',earliest_start:earliestInput.value?toISO(earliestInput.value,tz.value):null});if(!t.id)t.remaining_minutes=t.estimated_minutes;const {id,...body}=t;await store.mutate(id?'/tasks/'+id:'/tasks',id?'PATCH':'POST',body);dialog.value=''})}
async function complete(t:Task){await store.run(async()=>{await store.mutate('/tasks/'+t.id,'PATCH',{status:t.status==='done'?'todo':'done',remaining_minutes:t.status==='done'?t.estimated_minutes:0});store.notify(t.status==='done'?'任务已恢复':'完成得不错，给自己一点休息时间')})}
const deletion=ref<{type:'task'|'project';id:string;title:string;returnTo:string}|null>(null)
const deletionDependencies=computed(()=>deletion.value?.type==='task'?data.value.tasks.filter(t=>t.dependencies.includes(deletion.value!.id)):[])
const deletionTaskCount=computed(()=>deletion.value?.type==='project'?data.value.tasks.filter(t=>t.project_id===deletion.value!.id).length:0)
function requestTaskDeletion(task:Task,returnTo=''){store.error='';deletion.value={type:'task',id:task.id,title:task.title,returnTo};dialog.value='delete'}
function requestProjectDeletion(project:Project){store.error='';deletion.value={type:'project',id:project.id,title:project.name,returnTo:''};dialog.value='delete'}
function cancelDeletion(){dialog.value=deletion.value?.returnTo||'';deletion.value=null;store.error=''}
async function confirmDeletion(){
 if(!deletion.value||deletionDependencies.value.length)return
 const target=deletion.value
 await store.run(async()=>{
  await store.mutate(`/${target.type==='task'?'tasks':'projects'}/${target.id}`,'DELETE')
  if(target.type==='project'&&projectFilter.value===target.id)projectFilter.value=''
  dialog.value='';deletion.value=null
  store.notify(target.type==='task'?'任务已删除，相关日历安排已释放':'项目已删除，其中的任务已保留在未分类中')
 })
}
const eventForm=ref({title:'',start_at:'',end_at:''})
function openEvent(){eventForm.value={title:'',start_at:today.value+'T09:00',end_at:today.value+'T10:00'};dialog.value='event'}
async function saveEvent(){await store.run(async()=>{await store.mutate('/calendar/events','POST',{title:eventForm.value.title,start_at:toISO(eventForm.value.start_at,tz.value),end_at:toISO(eventForm.value.end_at,tz.value)});dialog.value=''})}
const projectForm=ref({name:'',color:'#657d68'})
async function saveProject(){await store.run(async()=>{await store.mutate('/projects','POST',projectForm.value);projectForm.value={name:'',color:'#657d68'};dialog.value=''})}
const quickInput=ref(''),parsed=ref<Parsed|null>(null),parseSelected=ref<boolean[]>([])
async function parseInput(){if(!quickInput.value.trim())return;await store.run(async()=>{parsed.value=await api<Parsed>('/tasks/parse','POST',{text:quickInput.value});parseSelected.value=parsed.value.items.map(()=>true);dialog.value='parse'})}
async function saveParsed(){await store.run(async()=>{if(!parsed.value)return;const tasks=parsed.value.items.filter((_,i)=>parseSelected.value[i]).map(item=>normalizeTask({...item.task,id:'',remaining_minutes:item.task.estimated_minutes}));await store.mutate('/tasks/batch','POST',tasks);dialog.value='';quickInput.value='';store.notify('任务已加入，点击自动规划生成时间安排')})}
const filter=ref('all'),projectFilter=ref(''),search=ref('')
const filteredTasks=computed(()=>data.value.tasks.filter(t=>(!search.value||t.title.toLowerCase().includes(search.value.toLowerCase()))&&(!projectFilter.value||t.project_id===projectFilter.value)&&(filter.value==='all'||filter.value==='done'&&t.status==='done'||filter.value==='todo'&&t.status!=='done'||filter.value==='unscheduled'&&t.status!=='done'&&!activeBlocks.value.some(b=>b.task_id===t.id))).sort((a,b)=>a.status==='done'?1:b.status==='done'?-1:(a.deadline||a.deadline_date||'9999').localeCompare(b.deadline||b.deadline_date||'9999')))
const settingsDraft=ref<Settings|null>(null)
function openSettings(){settingsDraft.value=JSON.parse(JSON.stringify(data.value.settings));go('settings')}
async function saveSettings(){await store.run(async()=>{await store.mutate('/settings','PUT',settingsDraft.value);store.notify('时间偏好已保存，请重新规划')})}
async function plan(){await store.run(store.plan);if(store.preview)dialog.value='preview'}
async function seed(){await store.run(async()=>{await api('/demo','POST');await store.load();await store.plan();dialog.value='preview'})}
async function toggleLock(){await store.run(async()=>{if(!selectedBlock.value)return;await api('/schedule/blocks/'+selectedBlock.value.id,'PATCH',{is_locked:!selectedBlock.value.is_locked});await store.load();dialog.value='';store.notify('锁定状态已更新')})}
const chats=ref<{role:string;text:string}[]>([{role:'assistant',text:'你好，我是你的规划助手。告诉我需要完成的事情，或问问当前计划是否来得及。我会先给出建议，确认后再安排。'}]),chatInput=ref('')
async function sendChat(){if(!chatInput.value.trim())return;const text=chatInput.value;chatInput.value='';chats.value.push({role:'user',text});await store.run(async()=>{const result=await api('/ai/chat','POST',{text});chats.value.push({role:'assistant',text:result.message});if(result.preview){parsed.value=result.preview;parseSelected.value=result.preview.items.map(()=>true);dialog.value='parse'}})}
</script>

<template>
<div class="app-shell" v-if="store.data">
 <aside class="sidebar" :class="{visible:mobileNav}">
  <a class="brand" href="#" @click.prevent="go('today')"><span class="brand-mark"><Layers :size="22"/></span>FlowPilot<span class="brand-dot">®</span></a>
  <div class="workspace"><div class="avatar">L</div><div><strong>我的个人空间</strong><small>Personal workspace</small></div><MoreHorizontal :size="17"/></div>
  <span class="section-label">工作空间</span>
  <nav><button v-for="item in nav" :key="item.id" :class="{active:page===item.id}" @click="go(item.id)"><component :is="item.icon" :size="18"/>{{item.label}}<span v-if="item.id==='inbox'" class="nav-count">{{pending.length}}</span></button><button :class="{active:page==='assistant'}" @click="go('assistant')"><Sparkles :size="18"/>AI 助手<span class="tiny-tag">BETA</span></button></nav>
  <div class="section-heading"><span class="section-label">我的项目</span><button class="icon-button" aria-label="新建项目" @click="dialog='project'"><Plus :size="15"/></button></div>
  <div class="project-links"><button v-for="p in data.projects" :key="p.id" @click="projectFilter=p.id;go('inbox')"><span class="color-dot" :style="{background:p.color}"></span>{{p.name}}<small>{{pending.filter(t=>t.project_id===p.id).length}}</small></button><span v-if="!data.projects.length" class="muted small">用项目整理不同目标</span></div>
  <div class="sidebar-bottom"><div class="calm-card"><Leaf :size="22"/><strong>把精力留给重要的事</strong><p>让计划有条理，也让生活有留白。</p><button @click="openSettings">设置我的专注时段 <ArrowUpRight :size="14"/></button></div><button class="settings-link" @click="openSettings"><Settings2 :size="18"/>偏好设置<span class="version">v0.1</span></button><div class="local-status"><span></span>本地个人版 · 数据保存在此设备</div></div>
 </aside>
 <div class="workspace-main">
  <header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-toggle" aria-label="展开导航" @click="mobileNav=!mobileNav"><Menu :size="20"/></button><span>工作空间</span><span>/</span><strong>{{nav.find(n=>n.id===page)?.label||({settings:'偏好设置',assistant:'AI 助手'} as any)[page]}}</strong></div><div class="top-actions"><span class="timezone-label"><span class="status-dot"></span>{{tz}}</span><button class="icon-button" aria-label="打开设置" @click="openSettings"><Settings2 :size="18"/></button><div class="avatar small-avatar">L</div></div></header>
  <main>
   <div class="page-heading"><div><div class="eyebrow">{{dateLabel}} <span>·</span> MAKE ROOM FOR WHAT MATTERS</div><h1>{{page==='today'?'让今天，从容有序。':page==='calendar'?'把每一件事，放在合适的时间。':page==='inbox'?'清空脑海，收进任务箱。':page==='projects'?'让每个目标，向前一步。':page==='stats'?'看见每一份专注。':page==='settings'?'找到适合你的节奏。':'一起，为重要的事留出时间。'}}</h1><p>{{page==='today'?'规划交给 FlowPilot，你只需专注当下。':page==='settings'?'你的时间，由你定义。所有排程都会遵守这些时段。':'任务、时间与优先级，在这里连接起来。'}}</p></div><button v-if="page!=='settings'" class="primary" :disabled="store.busy" @click="plan"><LoaderCircle v-if="store.busy" :size="17" class="spin"/><Sparkles v-else :size="17"/>自动规划<kbd>↵</kbd></button></div>
   <div class="error-banner" v-if="store.error" role="alert"><AlertCircle :size="18"/><span>{{store.error}}</span><button aria-label="关闭错误" @click="store.error=''"><X :size="16"/></button></div>
   <form v-if="page!=='settings'" class="quick-input" @submit.prevent="parseInput"><span class="sparkle-box"><Sparkles :size="20"/></span><input v-model="quickInput" aria-label="自然语言任务输入" placeholder="告诉我你的计划，比如：周五晚上8点前完成电磁场作业，需要3小时…"/><span class="input-hint">一句话，安排好</span><button class="icon-button send-button" type="submit" :disabled="store.busy||!quickInput.trim()" aria-label="解析任务"><ArrowRight :size="20"/></button></form>
   <div class="dirty-banner" v-if="store.dirty"><span><span class="status-dot"></span>任务或时间偏好已更新，重新规划后查看新安排。</span><button @click="plan">预览新计划 <ArrowRight :size="14"/></button></div>
   <template v-if="page==='today'||page==='calendar'">
    <div class="stat-grid" v-if="page==='today'"><div class="stat-card"><span class="stat-icon sage"><Clock3 :size="20"/></span><div><span class="stat-caption">今日计划时长</span><strong>{{hours(todayBlocks.reduce((s,b)=>s+(new Date(b.end_at).getTime()-new Date(b.start_at).getTime())/60000,0)).replace('h','')}}<small>小时</small></strong></div><span class="stat-foot">为专注留出空间</span></div><div class="stat-card"><span class="stat-icon lavender"><CheckCheck :size="20"/></span><div><span class="stat-caption">待完成任务</span><strong>{{pending.length}}<small>项任务</small></strong></div><span class="stat-foot">{{completed.length}} 项已完成</span></div><div class="stat-card"><span class="stat-icon amber"><AlertCircle :size="20"/></span><div><span class="stat-caption">临近截止</span><strong>{{urgent.length}}<small>项任务</small></strong></div><span class="stat-foot">未来 48 小时内</span></div></div>
    <div class="planning-layout"><section class="calendar-panel panel"><div class="calendar-toolbar"><div><h2>我的日程 <span class="live-label"><span></span>AI 规划</span></h2><p>{{calTitle}}</p></div><div class="calendar-controls"><button class="outline today-button" @click="navigate(0)">今天</button><button class="icon-button" aria-label="上一周期" @click="navigate(-1)"><ChevronLeft :size="17"/></button><button class="icon-button" aria-label="下一周期" @click="navigate(1)"><ChevronRight :size="17"/></button><div class="view-switch"><button :class="{selected:calendarView==='timeGridDay'}" @click="changeView('timeGridDay')">日</button><button :class="{selected:calendarView==='timeGridWeek'}" @click="changeView('timeGridWeek')">周</button><button :class="{selected:calendarView==='dayGridMonth'}" @click="changeView('dayGridMonth')">月</button></div><button class="icon-button add-event" aria-label="添加固定日程" @click="openEvent"><Plus :size="19"/></button></div></div><div class="calendar-legend"><span><i style="background:#657d68"></i>学习 / 专注</span><span><i style="background:#8b80aa"></i>科研 / 项目</span><span><i style="background:#b98960"></i>固定日程</span><span class="legend-end"><LockKeyhole :size="12"/>拖动安排后自动锁定</span></div><div class="calendar-wrap"><FullCalendar ref="calendar" :options="calendarOptions"/></div><div class="calendar-footer"><span><Sparkles :size="14"/>仅在可用时段安排，给生活留一点余地。</span><button :disabled="!data.can_undo||store.busy" @click="store.run(async()=>{await api('/schedule/undo','POST');await store.load();store.notify('已恢复上一版排程')})"><Undo2 :size="14"/>撤销上次规划</button></div></section>
    <aside class="insight-column"><section class="assistant-card"><div class="assistant-header"><span class="sparkle-box"><Sparkles :size="20"/></span><span>你的规划助手<small>让安排更懂你</small></span><span class="online-dot"></span></div><p v-if="!pending.length">从一件小事开始吧。添加任务后，我会结合你的空闲时间，帮你找到合适的安排。</p><p v-else>有 <strong>{{pending.length}}</strong> 件事等你推进。{{riskList.length?'先关注时间紧张的任务，再从容处理其他安排。':'计划已准备好，专注做好眼前的一件事。'}}</p><button @click="go('assistant')">和 AI 聊聊我的计划 <ArrowUpRight :size="16"/></button></section>
    <section class="panel compact-panel"><div class="panel-title"><h3>截止提醒</h3><span class="badge">{{riskList.length}}</span></div><div v-if="!riskList.length" class="quiet-empty"><Check :size="20"/><p>{{pending.length?'当前没有截止风险':'添加任务后在这里查看提醒'}}</p></div><div v-for="risk in riskList.slice(0,3)" :key="risk.task_id" class="risk-item" :class="risk.level"><div class="risk-top"><span class="color-dot"></span><strong>{{risk.title}}</strong></div><p>{{risk.message}}</p><button @click="openTask(taskById(risk.task_id))">查看任务 <ArrowUpRight :size="12"/></button></div></section>
    <section class="panel compact-panel"><div class="panel-title"><h3>完成进度</h3><span class="muted small">{{completed.length}} / {{data.tasks.length}}</span></div><div class="progress-display"><strong>{{progress}}<small>%</small></strong><span>每一步，都算数。</span></div><div class="progress-track"><i :style="{width:progress+'%'}"></i></div><div class="mini-task" v-for="t in pending.slice(0,3)" :key="t.id"><button class="check-button" :aria-label="'完成'+t.title" @click="complete(t)"><Circle :size="17"/></button><button @click="openTask(t)">{{t.title}}</button><span>{{hours(t.remaining_minutes)}}</span></div></section>
    <div v-if="!data.tasks.length" class="demo-card"><strong>先体验一下？</strong><p>加载相对当前日期生成的示例任务与课程，查看自动规划效果。</p><button class="outline" :disabled="store.busy" @click="seed">加载示例数据 <ArrowRight :size="14"/></button></div><div class="soft-quote" v-else><Sun :size="22"/><p>好的计划，也包括休息。</p></div></aside></div>
   </template>
   <template v-if="page==='inbox'"><section class="panel inbox-panel"><div class="list-toolbar"><div class="tabs"><button v-for="[id,label] in [['all','全部任务'],['todo','待完成'],['unscheduled','未安排'],['done','已完成']]" :class="{selected:filter===id}" @click="filter=id!">{{label}}</button></div><button class="primary" @click="openTask()"><Plus :size="16"/>新建任务</button></div><div class="filter-bar"><label class="search-field"><Search :size="16"/><input v-model="search" placeholder="搜索任务" aria-label="搜索任务"/></label><select v-model="projectFilter" aria-label="按项目筛选"><option value="">所有项目</option><option v-for="p in data.projects" :value="p.id">{{p.name}}</option></select></div><div class="task-table"><div class="table-header"><span>任务名称</span><span>项目</span><span>截止时间</span><span>剩余耗时</span><span>状态</span><span class="operations-label">操作</span></div><div v-for="t in filteredTasks" :key="t.id" class="task-row"><div class="task-name"><button class="check-button" :class="{checked:t.status==='done'}" :aria-label="t.status==='done'?'恢复任务':'完成任务'" @click="complete(t)"><Check v-if="t.status==='done'" :size="16"/><Circle v-else :size="18"/></button><button :class="{struck:t.status==='done'}" @click="openTask(t)">{{t.title}}<small class="priority" :class="'priority-'+t.priority">{{['','低优先级','中优先级','高优先级'][t.priority]}}</small></button></div><span class="project-tag" :style="{color:color(t)}">{{projectById(t.project_id)?.name||'未分类'}}</span><span class="small">{{deadlineLabel(t)}}</span><span class="small">{{hours(t.remaining_minutes)}}</span><span class="state-tag" :class="{done:t.status==='done'}">{{t.status==='done'?'已完成':activeBlocks.some(b=>b.task_id===t.id)?'已排程':'待安排'}}</span><button class="icon-button delete-button" :aria-label="'删除任务：'+t.title" title="删除任务" :disabled="store.busy" @click="requestTaskDeletion(t)"><Trash2 :size="16"/></button></div></div><div class="large-empty" v-if="!filteredTasks.length"><Inbox :size="34"/><h3>{{data.tasks.length?'没有符合条件的任务':'给想做的事，一个开始'}}</h3><p>添加任务，FlowPilot 会帮你找到适合的时间。</p><button class="outline" @click="openTask()"><Plus :size="16"/>添加第一项任务</button></div></section><section class="panel events-list"><div class="panel-title"><h3>固定日程</h3><button class="text-button" @click="openEvent"><Plus :size="15"/>添加课程 / 会议</button></div><div v-for="e in [...data.events].sort((a,b)=>a.start_at.localeCompare(b.start_at))" class="event-list-row"><CalendarDays :size="17"/><strong>{{e.title}}</strong><span>{{wallTime(e.start_at,tz).replace('T',' ').slice(0,16)}} — {{timeLabel(e.end_at)}}</span><button class="icon-button" aria-label="查看固定日程" @click="selectedEvent=e;dialog='eventDetail'"><MoreHorizontal :size="18"/></button></div><p v-if="!data.events.length" class="muted small">添加固定课程、会议，它们将优先占用时间。</p></section></template>
   <template v-if="page==='projects'"><div class="content-toolbar"><h2>我的项目 <span class="muted">{{data.projects.length}}</span></h2><button class="primary" @click="dialog='project'"><Plus :size="16"/>新建项目</button></div><div class="projects-grid"><article v-for="p in data.projects" :key="p.id" class="panel project-card"><button class="project-open" :aria-label="'打开项目：'+p.name" @click="projectFilter=p.id;go('inbox')"><span class="project-symbol" :style="{color:p.color,background:p.color+'18'}"><Layers :size="25"/></span><ArrowUpRight class="project-arrow" :size="19"/><h2>{{p.name}}</h2><p>{{data.tasks.filter(t=>t.project_id===p.id).length}} 个任务 · {{hours(data.tasks.filter(t=>t.project_id===p.id&&t.status!=='done').reduce((s,t)=>s+t.remaining_minutes,0))}} 剩余工作量</p><div class="progress-track"><i :style="{width:(data.tasks.filter(t=>t.project_id===p.id).length?100*data.tasks.filter(t=>t.project_id===p.id&&t.status==='done').length/data.tasks.filter(t=>t.project_id===p.id).length:0)+'%',background:p.color}"></i></div></button><button class="icon-button delete-button project-delete" :aria-label="'删除项目：'+p.name" title="删除项目" :disabled="store.busy" @click="requestProjectDeletion(p)"><Trash2 :size="17"/></button></article><button class="new-project-card" @click="dialog='project'"><Plus :size="25"/>创建一个新目标</button></div></template>
   <template v-if="page==='stats'"><div class="stat-grid"><div class="panel metric"><span>已完成任务</span><strong>{{completed.length}}</strong><small>累计完成</small></div><div class="panel metric"><span>已记录完成工作量</span><strong>{{hours(data.tasks.reduce((s,t)=>s+t.estimated_minutes-t.remaining_minutes,0))}}</strong><small>根据任务进度计算，非专注计时</small></div><div class="panel metric"><span>待安排工作量</span><strong>{{hours(data.schedule.risks.reduce((s,r)=>s+r.unscheduled_minutes,0))}}</strong><small>当前已发布方案</small></div></div><section class="panel stats-panel"><h2>项目完成情况</h2><p class="muted small">将目标化为一步步可见的进展。</p><div v-for="p in data.projects" class="project-stat"><strong><span class="color-dot" :style="{background:p.color}"></span>{{p.name}}</strong><div class="progress-track"><i :style="{background:p.color,width:(data.tasks.filter(t=>t.project_id===p.id).length?100*data.tasks.filter(t=>t.project_id===p.id&&t.status==='done').length/data.tasks.filter(t=>t.project_id===p.id).length:0)+'%'}"></i></div><span>{{data.tasks.filter(t=>t.project_id===p.id&&t.status==='done').length}} / {{data.tasks.filter(t=>t.project_id===p.id).length}}</span></div><p v-if="!data.projects.length" class="muted">创建项目并完成任务后，这里会呈现你的进展。</p></section></template>
   <template v-if="page==='settings'&&settingsDraft"><form class="panel settings-panel" @submit.prevent="saveSettings"><h2>规划偏好</h2><div class="form-grid"><label>时区<input v-model="settingsDraft.timezone" required placeholder="Asia/Shanghai"/><small>使用 IANA 时区，日历和日期解析将按此显示。</small></label><label>规划窗口（天）<input type="number" v-model.number="settingsDraft.horizon_days" min="1" max="28" required/></label><label>排程引擎<select v-model="settingsDraft.engine"><option value="heuristic">快速启发式 · 优先保留现有安排</option><option value="cp-sat">CP-SAT · 全局限时优化</option></select><small>未安装 OR-Tools 时自动回退，预览会显示实际引擎。</small></label></div><div class="settings-section-title"><div><h3>每周可用时段</h3><p>系统只会安排在这些时段内；课表与会议将自动扣除。</p></div><button type="button" class="outline" @click="settingsDraft.availability.push({weekday:0,start_time:'09:00',end_time:'12:00'})"><Plus :size="16"/>添加时段</button></div><div class="availability-row" v-for="(rule,index) in settingsDraft.availability" :key="index"><select v-model.number="rule.weekday" aria-label="星期"><option v-for="(day,i) in ['周一','周二','周三','周四','周五','周六','周日']" :value="i">{{day}}</option></select><input type="time" v-model="rule.start_time" step="900" required aria-label="开始时间"/><span>至</span><input type="time" v-model="rule.end_time" step="900" required aria-label="结束时间"/><button type="button" class="icon-button" aria-label="删除时段" @click="settingsDraft.availability.splice(index,1)"><Trash2 :size="16"/></button></div><p v-if="!settingsDraft.availability.length" class="muted">尚无可用时间。排程会保留所有未安排工作量并提示风险。</p><div class="settings-footer"><span class="muted small">模型接入通过后端环境变量配置，详见项目 README。</span><button class="primary" :disabled="store.busy" type="submit">保存偏好 <Check :size="16"/></button></div></form></template>
   <template v-if="page==='assistant'"><section class="panel chat-panel"><div class="assistant-chat-title"><Sparkles :size="23"/><div><h2>你的时间，我们一起规划</h2><p>任务提取 · 当前计划风险分析 · 确认后执行</p></div></div><div class="messages"><div v-for="(message,index) in chats" :key="index" class="message" :class="message.role"><span class="message-avatar"><Sparkles v-if="message.role==='assistant'" :size="16"/><span v-else>我</span></span><p>{{message.text}}</p></div></div><div class="chat-suggestions"><button @click="chatInput='我能完成所有任务吗？';sendChat()">分析我的截止风险</button><button @click="chatInput='明天晚上8点前读完论文，需要2小时'">添加明天的任务</button></div><form class="chat-input" @submit.prevent="sendChat"><input v-model="chatInput" placeholder="告诉我你的任务，或者问问当前的计划…" aria-label="AI对话"/><button class="primary" :disabled="store.busy||!chatInput.trim()"><Send :size="17"/></button></form><small class="muted">AI 提取结果需要确认。最终排程由约束引擎计算。</small></section></template>
   <footer class="page-footer"><span>FlowPilot <span class="footer-separator">/</span> Your time, thoughtfully planned.</span><span><span class="status-dot"></span>属于你的每一天</span></footer>
  </main>
 </div>
 <Transition name="toast"><div v-if="store.toast" role="status" class="toast"><Check :size="17"/>{{store.toast}}</div></Transition>
 <div v-if="dialog" class="modal-backdrop" @click.self="!store.busy&&(dialog='')"><section class="modal" :class="{'wide-modal':['preview','parse'].includes(dialog)}" role="dialog" aria-modal="true" :aria-label="({task:'任务详情',event:'新增固定日程',project:'新建项目',preview:'排程预览',parse:'确认任务',block:'时间块详情',eventDetail:'固定日程详情',delete:deletion?.type==='project'?'删除项目':'删除任务'} as any)[dialog]" @keydown.esc="!store.busy&&(dialog='')"><button class="modal-close icon-button" aria-label="关闭弹窗" :disabled="store.busy" @click="dialog=''"><X :size="20"/></button>
  <template v-if="dialog==='task'"><span class="eyebrow">TASK DETAILS</span><h2>{{draft.id?'任务详情':'一件新的重要小事'}}</h2><form @submit.prevent="saveTask" class="dialog-form"><label>任务名称<input v-model="draft.title" required maxlength="240" placeholder="你想完成什么？" autofocus/></label><div class="form-grid"><label>所属项目<select v-model="draft.project_id"><option :value="null">未分类</option><option v-for="p in data.projects" :value="p.id">{{p.name}}</option></select></label><label>优先级<select v-model.number="draft.priority"><option :value="1">低</option><option :value="2">中</option><option :value="3">高</option></select></label><label>预计耗时（分钟）<input type="number" step="15" min="15" max="10080" v-model.number="draft.estimated_minutes" required/></label><label v-if="draft.id">剩余耗时（分钟）<input type="number" step="15" min="0" :max="draft.estimated_minutes" v-model.number="draft.remaining_minutes" required/></label><label>截止精度<select v-model="deadlineMode" @change="deadlineInput='' "><option value="exact">具体日期时间</option><option value="date">只有日期（待确认）</option></select></label><label>截止时间<input :type="deadlineMode==='exact'?'datetime-local':'date'" v-model="deadlineInput"/><small>{{tz}} · 留空表示暂无截止日期</small></label><label>截止要求<select v-model="draft.deadline_type"><option value="none">暂无</option><option value="hard">硬截止</option><option value="soft">软截止</option></select></label><label>最早开始<input type="datetime-local" v-model="earliestInput"/></label><label>偏好时段<select v-model="draft.preferred_period"><option value="any">不限</option><option value="morning">上午</option><option value="afternoon">下午</option><option value="evening">晚上</option></select></label><label>任务状态<select v-model="draft.status"><option value="todo">待开始</option><option value="in_progress">进行中</option><option value="done">已完成</option></select></label></div><label class="checkbox-label"><input type="checkbox" v-model="draft.splittable"/>允许拆分为多个专注时间块</label><div v-if="draft.splittable" class="form-grid"><label>单次最短（分钟）<input type="number" step="15" min="15" max="480" v-model.number="draft.min_block_minutes" required/></label><label>单次最长（分钟）<input type="number" step="15" min="15" max="1440" v-model.number="draft.max_block_minutes" required/></label></div><label>前置任务（可多选）<select multiple v-model="draft.dependencies"><option v-for="t in data.tasks.filter(t=>t.id!==draft.id)" :value="t.id">{{t.title}}</option></select><small>前置任务完成后才会安排当前任务，循环依赖将被拒绝。</small></label><label>备注<textarea v-model="draft.notes" rows="2"/></label><div class="modal-actions"><button v-if="draft.id" class="text-button danger-text" type="button" @click="requestTaskDeletion(draft,'task')" :disabled="store.busy"><Trash2 :size="15"/>删除任务</button><button class="primary" :disabled="store.busy" type="submit">保存任务 <Check :size="16"/></button></div></form></template>
  <template v-if="dialog==='delete'&&deletion">
   <span class="eyebrow">{{deletion.type==='task'?'DELETE TASK':'DELETE PROJECT'}}</span>
   <h2>{{deletion.type==='task'?'删除任务':'删除项目'}}？</h2>
   <p class="delete-target-name">{{deletion.title}}</p>
   <template v-if="deletion.type==='task'">
    <p class="muted small">任务及其日历安排将被移除，释放的时间可以重新规划。此操作不可撤销。</p>
    <div v-if="deletionDependencies.length" class="delete-dependencies" role="status">
     <p>以下任务依赖此任务，请先打开它们，在「前置任务」中解除依赖后再删除：</p>
     <button v-for="task in deletionDependencies" :key="task.id" class="text-button" @click="openTask(task)">{{task.title}} <ArrowUpRight :size="13"/></button>
    </div>
   </template>
   <p v-else class="muted small">项目中的 {{deletionTaskCount}} 个任务将保留并移到「未分类」，已有日历安排保持不变。删除项目不可撤销。</p>
   <div class="modal-actions">
    <button class="outline" :disabled="store.busy" @click="cancelDeletion">取消</button>
    <button class="danger-button" :disabled="store.busy||deletionDependencies.length>0" @click="confirmDeletion"><LoaderCircle v-if="store.busy" :size="16" class="spin"/><Trash2 v-else :size="16"/>{{deletion.type==='task'?'确认删除任务':'确认删除项目'}}</button>
   </div>
  </template>
  <template v-if="dialog==='event'"><span class="eyebrow">FIXED EVENT</span><h2>给固定日程留个位置</h2><p class="muted small">课程和会议会占用时间，AI 不会移动它们。{{tz}}</p><form @submit.prevent="saveEvent" class="dialog-form"><label>日程名称<input v-model="eventForm.title" required placeholder="课程、会议或其他固定安排"/></label><label>开始时间<input type="datetime-local" v-model="eventForm.start_at" required step="900"/></label><label>结束时间<input type="datetime-local" v-model="eventForm.end_at" required step="900"/></label><div class="modal-actions"><button class="primary" :disabled="store.busy">保存日程</button></div></form></template>
  <template v-if="dialog==='project'"><span class="eyebrow">NEW PROJECT</span><h2>为新目标命名</h2><form class="dialog-form" @submit.prevent="saveProject"><label>项目名称<input v-model="projectForm.name" maxlength="80" required placeholder="比如：海雾研究"/></label><label>项目颜色<input type="color" v-model="projectForm.color"/></label><div class="modal-actions"><button class="primary" :disabled="store.busy">创建项目</button></div></form></template>
  <template v-if="dialog==='preview'&&store.preview"><span class="eyebrow">A LITTLE MORE CLARITY</span><h2>这是为你准备的新计划</h2><p class="muted small">{{store.preview.engine}} · 新增 {{store.preview.changes.added}} 块 · 移除 {{store.preview.changes.removed}} 块 · 保留 {{store.preview.changes.retained}} 块</p><div class="preview-summary"><Sparkles :size="20"/><p>已考虑固定日程、任务依赖和可用时段。锁定与正在执行的安排保持原位。</p></div><div class="preview-risk" v-for="r in store.preview.risks.filter(r=>r.level==='danger'||r.deadline_needs_confirmation)"><AlertCircle :size="17"/><div><strong>{{r.title}}</strong><p>{{r.message}}</p></div></div><div class="preview-list"><div class="preview-row" v-for="b in store.preview.blocks" :key="b.id"><span class="color-dot" :style="{background:color(taskById(b.task_id))}"></span><div><strong>{{taskById(b.task_id)?.title}}</strong><small>{{b.reason}}</small></div><span>{{wallTime(b.start_at,tz).slice(5,10)}}<br/>{{timeLabel(b.start_at)}} — {{timeLabel(b.end_at)}}</span><LockKeyhole v-if="b.is_locked" :size="15"/></div><div class="large-empty" v-if="!store.preview.blocks.length"><CalendarDays :size="28"/><p>没有可排入的任务。检查任务、锁定状态和可用时间。</p></div></div><div class="modal-actions"><button class="outline" @click="dialog=''">暂不应用</button><button class="primary" :disabled="store.busy" @click="store.run(async()=>{await store.commit();dialog=''})">确认并应用 <Check :size="16"/></button></div></template>
  <template v-if="dialog==='parse'&&parsed"><span class="eyebrow">FROM THOUGHT TO PLAN</span><h2>把想法，变成行动</h2><p class="muted small">{{parsed.notice}}</p><form class="dialog-form" @submit.prevent="saveParsed"><div class="parsed-item" v-for="(item,i) in parsed.items" :key="i"><label class="checkbox-label"><input type="checkbox" v-model="parseSelected[i]"/>加入此任务 <span class="muted small">{{Math.round(item.confidence*100)}}% 提取置信度</span></label><label>任务名称<input v-model="item.task.title" required/></label><div class="form-grid"><label>耗时（分钟）<input type="number" step="15" min="15" max="10080" v-model.number="item.task.estimated_minutes" required/></label><label>优先级<select v-model.number="item.task.priority"><option :value="1">低</option><option :value="2">中</option><option :value="3">高</option></select></label><label>截止时间<input type="datetime-local" :value="item.task.deadline?wallTime(item.task.deadline,tz).slice(0,16):''" @change="item.task.deadline=($event.target as HTMLInputElement).value?toISO(($event.target as HTMLInputElement).value,tz):null;item.task.deadline_date=null;item.task.deadline_type=item.task.deadline?'hard':'none'"/><small v-if="item.task.deadline_date">仅日期：{{item.task.deadline_date}} · 尚未设硬截止</small></label></div><div class="parse-warning" v-for="issue in item.issues"><AlertCircle :size="14"/>{{issue}}</div></div><div class="modal-actions"><span class="muted small">保存即确认勾选的字段；随后可编辑完整约束。</span><button class="primary" :disabled="store.busy||!parseSelected.some(Boolean)">确认并加入任务箱 <Check :size="16"/></button></div></form></template>
  <template v-if="dialog==='block'&&selectedBlock"><span class="eyebrow">FOCUS BLOCK</span><h2>{{taskById(selectedBlock.task_id)?.title}}</h2><p class="block-time">{{wallTime(selectedBlock.start_at,tz).slice(0,10)}} · {{timeLabel(selectedBlock.start_at)}} — {{timeLabel(selectedBlock.end_at)}}</p><div class="preview-summary"><Sparkles :size="20"/><p>{{selectedBlock.reason}}</p></div><p class="muted small">锁定后重新规划将保留该时间。拖动或拉伸时间块也会自动锁定。</p><div class="modal-actions"><button class="outline" @click="openTask(taskById(selectedBlock!.task_id))">查看任务</button><button class="primary" :disabled="store.busy||new Date(selectedBlock.start_at)<=clock" @click="toggleLock"><LockKeyhole :size="16"/>{{selectedBlock.is_locked?'解除锁定':'锁定安排'}}</button></div></template>
  <template v-if="dialog==='eventDetail'&&selectedEvent"><span class="eyebrow">FIXED EVENT</span><h2>{{selectedEvent.title}}</h2><p>{{wallTime(selectedEvent.start_at,tz).slice(0,10)}} · {{timeLabel(selectedEvent.start_at)}} — {{timeLabel(selectedEvent.end_at)}}</p><p class="muted">这是固定日程，自动规划会避开这段时间。</p><div class="modal-actions"><button class="outline danger-text" :disabled="store.busy" @click="store.run(async()=>{await store.mutate('/calendar/events/'+selectedEvent!.id,'DELETE');dialog=''})"><Trash2 :size="15"/>删除固定日程</button></div></template>
  <div class="modal-error" v-if="store.error" role="alert">{{store.error}}</div>
 </section></div>
</div>
<div class="loading-screen" v-else><span class="brand-mark"><Layers :size="26"/></span><h1>FlowPilot</h1><p v-if="!store.error">正在为你打开新的一天…</p><template v-else><p>{{store.error}}</p><p>请确认后端已启动（127.0.0.1:8000）。</p><button class="primary" @click="store.run(store.load)">重新连接</button></template></div>
</template>
